<?php
use App\Core\DB;use App\Core\Auth;use App\Core\Csrf;use App\Core\U;use App\Core\Audit;use App\Core\Secret;use App\Core\Site;use App\Services\ReservationService;use App\Services\GeminiService;use App\Services\UploadService;use App\Services\ICalService;use App\Controllers\WhatsappController;
if (!defined('SUITES_PAGE_ENTRY')) { http_response_code(404); exit; }

  $t=$_SESSION['traveler']??null;if(!$t){U::redirect('index.php?p=traveler');}
  $q=$pdo->prepare("SELECT v.code,r.code reservation_code,r.checkin,r.checkout,r.guests,r.total,g.name guest,rm.name room,p.name property_name,p.address,p.address_number,p.city,p.state,p.phone,p.checkin property_checkin,p.house_rules FROM vouchers v JOIN reservations r ON r.id=v.reservation_id JOIN guests g ON g.id=r.guest_id JOIN rooms rm ON rm.id=r.room_id JOIN property p ON p.id=1 WHERE r.id=? AND r.guest_id=?");$q->execute([$t['reservation_id'],$t['guest_id']]);$v=$q->fetch();if(!$v){render('Voucher','<div class="alert error">Voucher ainda não disponível.</div>');exit;}
  $h='<div class="card voucher"><h1>Voucher</h1><p><b>Código:</b> '.U::e($v['code']).'</p><p><b>Reserva:</b> '.U::e($v['reservation_code']).'</p><p><b>Hóspede:</b> '.U::e($v['guest']).'</p><p><b>Acomodação:</b> '.U::e($v['room']).'</p><p><b>Período:</b> '.U::e($v['checkin']).' a '.U::e($v['checkout']).'</p><p><b>Hóspedes:</b> '.U::e($v['guests']).'</p><p><b>Valor:</b> '.money((float)$v['total']).'</p><hr><h2>'.U::e($v['property_name']).'</h2><p>'.U::e($v['address']).' '.U::e($v['address_number']).' - '.U::e($v['city']).'/'.U::e($v['state']).'</p><p>Telefone: '.U::e($v['phone']).'</p><p>Check-in: '.U::e($v['property_checkin']).'</p><p>'.nl2br(U::e($v['house_rules'])).'</p><button onclick="window.print()">Imprimir</button></div>';render('Voucher',$h);exit;
